from datetime import date

class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = {}  # book_id -> (borrower, borrow_date) or None if available
        self.user_borrows = {}  # user -> [(book_id, borrow_date, return_date)]
        self.user_fines = {}  # user -> total unpaid fine amount

    def add_book(self, book_id: str) -> None:
        self.books[book_id] = None

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is not None:
            raise ValueError(f"Book {book_id} is already borrowed")

        # Check if user has unpaid fines and already holds a book
        if user in self.user_fines and self.user_fines[user] > 0:
            # Count how many books the user currently has (not returned yet)
            current_books = 0
            if user in self.user_borrows:
                for book, borrow_date, return_date in self.user_borrows[user]:
                    if return_date is None:
                        current_books += 1
            if current_books >= 1:
                raise ValueError(f"User {user} has unpaid fines and already holds a book")

        # Record the borrow
        self.books[book_id] = (user, day)

        # Initialize user's borrow history if needed
        if user not in self.user_borrows:
            self.user_borrows[user] = []

        self.user_borrows[user].append((book_id, day, None))

        # Initialize user's fine if needed
        if user not in self.user_fines:
            self.user_fines[user] = 0.0

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.books:
            raise ValueError(f"Book {book_id} does not exist")

        if self.books[book_id] is None:
            raise ValueError(f"Book {book_id} is not borrowed")

        borrower, borrow_date = self.books[book_id]
        if borrower != user:
            raise ValueError(f"Book {book_id} was not borrowed by user {user}")

        # Calculate fine
        due_date = borrow_date.replace(day=borrow_date.day + self.loan_days)
        # Handle month/year rollover properly
        # Since we only need to calculate days difference, use date arithmetic
        days_overdue = (day - due_date).days
        if days_overdue < 0:
            days_overdue = 0

        fine = days_overdue * self.daily_fine

        # Update book status
        self.books[book_id] = None

        # Update user's borrow history
        if user in self.user_borrows:
            for i, (b_id, b_date, r_date) in enumerate(self.user_borrows[user]):
                if b_id == book_id and r_date is None:
                    self.user_borrows[user][i] = (b_id, b_date, day)
                    break

        # Add fine to user's unpaid fines
        if user not in self.user_fines:
            self.user_fines[user] = 0.0
        self.user_fines[user] += fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.user_fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        if user in self.user_fines:
            self.user_fines[user] = 0.0
